 import { Group, PlaneGeometry, SRGBColorSpace } from 'three/webgpu';
import { MeshBasicNodeMaterial, uv, vec3, sample } from 'three/webgpu';
import { gsap } from 'gsap';

const ATLAS_WIDTH = 512;
const ATLAS_HEIGHT = 320;
const ATLAS_COLS = 1;
const ATLAS_ROWS = 1;

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};
  group.userData.interactive = false;

  const atlasIndex = config.atlasRegion?.atlas ?? 0;
  const srcRect = config.atlasRegion?.sourceRect ?? [0, 0, ATLAS_WIDTH, ATLAS_HEIGHT];
  const [srcX, srcY, srcW, srcH] = srcRect;

  const regionWidth = srcW / ATLAS_WIDTH;
  const regionHeight = srcH / ATLAS_HEIGHT;
  const u0 = srcX / ATLAS_WIDTH;
  const v0 = 1.0 - (srcY + srcH) / ATLAS_HEIGHT;
  const regionAspect = srcW / srcH;

  const planeWidth = regionAspect * 2;
  const planeHeight = 2;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  const positionAttribute = geometry.attributes.position;
  for (let i = 0; i < positionAttribute.count; i++) {
    const u = ((positionAttribute.getX(i) / planeWidth) + 0.5) * regionWidth + u0;
    const v = ((positionAttribute.getY(i) / planeHeight) + 0.5) * regionHeight + v0;
    geometry.attributes.uv.setXY(i, u, v);
  }
  if (positionAttribute.count === 4) {
    geometry.attributes.uv.setXY(3, u0, v0 + regionHeight);
  }

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
    depthWrite: false,
  });

  const cleanupRegistry = [];
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.minFilter = ctx.THREE.LinearFilter;
      tex.magFilter = ctx.THREE.LinearFilter;
      tex.generateMipmaps = false;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new ctx.THREE.Mesh(geometry, material);
  mesh.renderOrder = 1;
  group.add(mesh);

  group.userData.cleanup = () => {
    cleanupRegistry.forEach((fn) => fn());
    gsap.killTweensOf(group);
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
